-- composition of rule kernels L:eliminate_outer_join x P:CombinePartialFinalAggregate (datafusion), template product
SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT MIN (CASE WHEN (SELECT BOOL_AND (FALSE) FROM tp AS a2) THEN a1.c0 ELSE a1.c0 END) AS c0, 5e-324::float8 AS c1 FROM t0 AS a1 GROUP BY CUBE (a1.c0)) AS ka CROSS JOIN (SELECT a2.c5 AS c0, a2.c2 AS c1 FROM (ti AS a1 LEFT JOIN t3 AS a2 ON (a1.c1 = a2.c5)) WHERE a2.c1) AS kb;
-- pgfuzz:check kernel:product SELECT (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT MIN (CASE WHEN (SELECT BOOL_AND (FALSE) FROM tp AS a2) THEN a1.c0 ELSE a1.c0 END) AS c0, 5e-324::float8 AS c1 FROM t0 AS a1 GROUP BY CUBE (a1.c0)) AS ka) * (SELECT count(*) FROM (SELECT a2.c5 AS c0, a2.c2 AS c1 FROM (ti AS a1 LEFT JOIN t3 AS a2 ON (a1.c1 = a2.c5)) WHERE a2.c1) AS kb)
